function uniqueLast(rows) {
  if (!rows || rows.length === 0) return [];

  const map = new Map();
  for (const row of rows) {
    const id = row.id;
    const value = row.value;
    map.set(id, { id, value });
  }

  const result = [];
  const seenIds = new Set();

  for (const [id, data] of map.entries()) {
    if (!seenIds.has(id)) {
      result.push(data);
      seenIds.add(id);
    }
  }

  return result;
}

